solution:
fizzbuzz <- function(n) {
  result <- character(0)
  for (i in seq_len(n)) {
    if (i %% 15 == 0) {
      result <- c(result, "FizzBuzz")
    } else if (i %% 3 == 0) {
      result <- c(result, "Fizz")
    } else if (i %% 5 == 0) {
      result <- c(result, "Buzz")
    } else {
      result <- c(result, as.character(i))
    }
  }
  result
}
